    "cameraCount",
    "stolenProbability",
    "itvFailProbability",
    "vehiclesPerCycle",
    "vehicleIntervalMs",
    "ocrDelayMs"
];

// Check presence
for (const k of required) {
    if (p[k] === undefined) {
        node.error(`Missing required field: ${k}`, msg);
        return null;
    }
}

// Check types and ranges
if (!Number.isInteger(p.cameraCount) || p.cameraCount < 1)
    return node.error("cameraCount must be an integer >= 1", msg);

if (!isNumber(p.stolenProbability) || p.stolenProbability < 0 || p.stolenProbability > 1)
    return node.error("stolenProbability must be between 0 and 1", msg);

if (!isNumber(p.itvFailProbability) || p.itvFailProbability < 0 || p.itvFailProbability > 1)
    return node.error("itvFailProbability must be between 0 and 1", msg);

if (!Number.isInteger(p.vehiclesPerCycle) || p.vehiclesPerCycle < 1)
    return node.error("vehiclesPerCycle must be an integer >= 1", msg);

if (!Number.isInteger(p.vehicleIntervalMs) || p.vehicleIntervalMs < 0)
    return node.error("vehicleIntervalMs must be >= 0", msg);

if (!Number.isInteger(p.ocrDelayMs) || p.ocrDelayMs < 0)
    return node.error("ocrDelayMs must be >= 0", msg);

// If everything is OK
return msg;
